import { Card } from '@absoluteui/components/card';
import { Button } from '@absoluteui/components/button';

const host = document.createElement('div');
document.body.append(host);
const archive = document.createElement('button');
archive.type = 'button';
archive.textContent = 'Archive';
Button.enhance(archive);
Card.create(host, {
  title: 'Quarterly report',
  subtitle: 'Updated today',
  content: 'Revenue grew 4% compared to last quarter.',
  footer: archive,
  variant: 'raised',
});

import { Card } from '@absoluteui/components/card';

const host = document.createElement('div');
document.body.append(host);
const img = document.createElement('img');
img.src = '/images/alpha.png';
img.alt = '';
Card.create(host, {
  title: 'Project Alpha',
  subtitle: 'Owner: Ada Lovelace',
  media: img,
  interactive: { href: '/projects/alpha' },
  headingLevel: 2,
});

import { Surface } from '@absoluteui/components/card';

const panel = document.createElement('section');
document.body.append(panel);
const surface = Surface.apply(panel, { variant: 'sunken', padded: true });
surface.update({ variant: 'raised' });
